65	/// ycsb_profile_list — die 6 YCSB-Profile (A–F) als compile-time-Liste = die YCSB-Teilmenge der Workload-Achse W.
66	using ycsb_profile_list =
67	    mp::mp_list<std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_A_Read50Write50>,
68	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_B_Read95Write5>,
69	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_C_ReadOnly>,
70	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_D_ReadLatest>,
71	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_E_Scan95>,
72	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_F_ReadModifyWrite>>;
73	
74	inline constexpr std::size_t ycsb_profile_count = mp::mp_size<ycsb_profile_list>::value;
75	
76	/// workload_profile_list — die VOLLE compile-time-Workload-Achse W der 2D-Mess-Matrix (#31-Schritt-2):
77	/// die 6 YCSB-Profile (A–F) + die 2 Heavy-Profile (IH/LH). Alle 8 haben ein profile_by_name-Mess-Pendant
78	/// (ycsb_token != ""). Additiv am Ende angehängt (mp_push_back) → YCSB-Reihenfolge/-Teilmenge unverändert.
79	using workload_profile_list =
80	    mp::mp_push_back<ycsb_profile_list,
81	                     std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::InsertHeavy>,
82	                     std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::LookupHeavy>>;
83	
84	inline constexpr std::size_t workload_profile_count = mp::mp_size<workload_profile_list>::value;
85	
86	/// config_for — Hybrid: compile-time-WorkloadKind (YCSB A–F) → runtime-WorkloadConfig via profile_by_name
87	/// (bit-identisch delegiert, golden-neutral). seed/ops bleiben runtime (dynamische Achse).
88	[[nodiscard]] inline WorkloadConfig config_for(cmd::WorkloadKind k, std::uint64_t seed, std::size_t ops) {
89	    return profile_by_name(ycsb_token(k), seed, ops);
90	}
